import numpy as np

grid = np.array([
    [6, 5, 5, 5, 5, 5, 5, 6, 6, 9, 9, 5, 0, 9],
    [5, 9, 5, 5, 6, 0, 6, 6, 0, 9, 5, 6, 5, 6],
    [5, 5, 9, 5, 9, 6, 9, 5, 0, 5, 3, 5, 5, 9],
    [5, 6, 5, 5, 5, 6, 6, 5, 5, 6, 5, 9, 9, 6],
    [5, 6, 5, 5, 5, 5, 5, 5, 6, 5, 5, 6, 5, 5],
    [6, 5, 9, 9, 9, 5, 6, 5, 5, 5, 9, 0, 5, 5],
    [5, 3, 9, 9, 5, 5, 9, 6, 9, 0, 3, 0, 5, 6],
    [5, 5, 5, 5, 9, 5, 5, 9, 9, 0, 9, 5, 6, 5],
    [5, 5, 0, 5, 5, 0, 6, 5, 5, 5, 9, 9, 5, 5],
    [5, 9, 9, 6, 6, 5, 5, 5, 0, 5, 3, 5, 5, 5]
])
shape = grid.shape

print(f"Grid size: {shape[0]}x{shape[1]}")

print("\n" + "="*50)
print("Trying: value = ((r+c)*base) mod mod for non-5 cells")
print("="*50)

for base in [3, 5, 7, 9, 11, 13]:
    for mod in [7, 11, 13, 17, 19, 21, 23]:
        correct = 0
        total_non_5 = 0
        mismatched = []
        for r in range(shape[0]):
            for c in range(shape[1]):
                if grid[r, c] != 5:
                    total_non_5 += 1
                    predicted = ((r + c) * base) % mod
                    if predicted == grid[r, c]:
                        correct += 1
                    else:
                        mismatched.append((r, c, grid[r, c], predicted))
                    if len(mismatched) >= 5:
                        break
            if len(mismatched) >= 5:
                break
        if correct > 0 and len(mismatched) < 10:
            success_rate = correct / total_non_5
            print(f"value = ((r+c)*{base}) mod {mod}: {correct}/{total_non_5} ≈ {success_rate:.2%}")
            for r, c, actual, pred in mismatched:
                print(f"  ({r},{c}): actual={actual}, predicted={pred}")

# Let me also try some other formulas
print("\n" + "="*50)
print("Trying other formulas")
print("="*50)

for formula_name, formula_func in [
    ("(r+c)*r mod 7", lambda r,c: ((r+c)*r) % 7),
    ("(r+c)*c mod 7", lambda r,c: ((r+c)*c) % 7),
    ("(r*c+1) mod 10", lambda r,c: (r*c+1) % 10),
    ("(r+c*2) mod 13", lambda r,c: (r+c*2) % 13),
    ("(r+c+1) mod 5", lambda r,c: (r+c+1) % 5),
]:
    correct = 0
    total_non_5 = 0
    mismatched = []
    for r in range(shape[0]):
        for c in range(shape[1]):
            if grid[r, c] != 5:
                total_non_5 += 1
                predicted = formula_func(r, c)
                if predicted == grid[r, c]:
                    correct += 1
                else:
                    mismatched.append((r, c, grid[r, c], predicted))
                if len(mismatched) >= 5:
                    break
        if len(mismatched) >= 5:
            break
    if correct > 0 and len(mismatched) < 10:
        success_rate = correct / total_non_5
        print(f"{formula_name}: {correct}/{total_non_5} ≈ {success_rate:.2%}")
        for r, c, actual, pred in mismatched:
            print(f"  ({r},{c}): actual={actual}, predicted={pred}")

